def preflight(events, context):
    import boto3

    instance_id = events["instance_id"]
    expected_platform = events["expected_platform"]
    ssm = boto3.client("ssm")
    response = ssm.describe_instance_information(
        Filters=[{"Key": "InstanceIds", "Values": [instance_id]}]
    )
    nodes = response.get("InstanceInformationList", [])
    if len(nodes) != 1:
        raise RuntimeError(
            f"{instance_id} is not returned as an SSM managed node in this Region"
        )

    node = nodes[0]
    ping_status = node.get("PingStatus", "Unknown")
    platform_type = node.get("PlatformType", "Unknown")
    if ping_status != "Online":
        raise RuntimeError(
            f"{instance_id} is not Online in Systems Manager (PingStatus={ping_status})"
        )
    if platform_type != expected_platform:
        raise RuntimeError(
            f"{instance_id} platform is {platform_type}; expected {expected_platform}"
        )

    return {
        "instance_id": instance_id,
        "ping_status": ping_status,
        "platform_type": platform_type,
        "platform_name": node.get("PlatformName", ""),
        "platform_version": node.get("PlatformVersion", ""),
        "agent_version": node.get("AgentVersion", ""),
        "last_ping": str(node.get("LastPingDateTime", "")),
    }
